# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: "Pure TUI twin" look: everything monospace on a character grid, no
#          chrome beyond a Textual-style footer of key hints.
# ---------------------------------------------------------------------------
from __future__ import annotations

import reflex as rx

from ..sample import CELLS, KEY_HINTS, MODES
from .common import box_table, code_block, switcher


def _output(output: dict | None) -> rx.Component | None:
    if output is None:
        return None
    if output["kind"] == "table":
        text = box_table(output["columns"], output["rows"])
    elif output["kind"] == "reply":
        text = "\n".join([output["paragraph"], "", *[f" • {b}" for b in output["bullets"]]])
    else:
        text = output["text"]
    return rx.el.pre(text, class_name="output")


def _cell(cell: dict) -> rx.Component:
    focused = cell.get("focused", False)
    return rx.el.div(
        rx.el.div(
            rx.el.span(MODES[cell["mode"]]["icon"], class_name="prompt"),
            code_block(cell["code"], cursor=focused),
            class_name="input",
        ),
        _output(cell["output"]),
        class_name=f"cell m-{cell['mode']}" + (" is-focused" if focused else ""),
    )


def tui_page() -> rx.Component:
    return rx.el.div(
        rx.el.div(*[_cell(cell) for cell in CELLS], class_name="tui-body"),
        rx.el.div(
            *[
                rx.el.span(rx.el.span(key, class_name="key"), f" {label}", class_name="hint")
                for key, label in KEY_HINTS
            ],
            class_name="tui-footer",
        ),
        switcher("tui"),
        class_name="page mono tui",
    )
